import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# -------------------------------------------------------------------------
# Custom CUDA kernel for depthwise convolution (naïve implementation)
# -------------------------------------------------------------------------
depthwise_cpp_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>

torch::Tensor depthwise_cuda(torch::Tensor input, int in_channels, int out_channels,
                             int kernel_size, int stride, int padding, int dilation,
                             int height_out, int width_out) {
    auto size = input.numel();
    auto out = torch::zeros_like(input);
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    // Naïve kernel – one thread per output pixel
    depthwise_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        nullptr,
        out.data_ptr<float>(),
        input.size(0), in_channels, out_channels, kernel_size, stride, padding, dilation,
        height_out, width_out
    );
    return out;
}
'''

depthwise_kernel_source = r'''
__global__ void depthwise_kernel(const float* input, const float* weight, float* output,
                                  int N, int in_ch, int out_ch, int k, int s, int p, int d,
                                  int H_out, int W_out) {
    int ih = blockIdx.y * blockDim.y + threadIdx.y;
    int iw = blockIdx.x * blockDim.x + threadIdx.x;
    if (ih >= H_out || iw >= W_out) return;

    for (int oc = 0; oc < out_ch; ++oc) {
        float sum = 0.0f;
        for (int kh = 0; kh < k; ++kh) {
            for (int kw = 0; kw < k; ++kw) {
                int ih_src = ih * s + kh * d - p;
                int iw_src = iw * s + kw * d - p;
                if (ih_src >= 0 && ih_src < input.shape[2]) &&
                   (iw_src >= 0 && iw_src < input.shape[3]) {
                    int idx = (blockIdx.z * N * input.shape[2] * input.shape[3] +
                               (blockIdx.z * N + oc) * input.shape[2] * input.shape[3] +
                               ih * input.shape[3] + iw * input.shape[3]);
                    sum += input[idx];
                }
            }
        }
        output[(ih * W_out + iw)] = sum;
    }
}
'''

# -------------------------------------------------------------------------
# Custom CUDA kernel for pointwise (1x1) convolution
# -------------------------------------------------------------------------
pointwise_cpp_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>

torch::Tensor pointwise_cuda(torch::Tensor input, int in_channels, int out_channels,
                             int kernel_size=1, int stride=1, int padding=0, int dilation=1,
                             int height_out=0, int width_out=0) {
    auto size = input.numel();
    auto out = torch::zeros_like(input);
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    pointwise_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        input.data_ptr<float>() , // placeholder weight
        out.data_ptr<float>(),
        input.size(0), in_channels, out_channels, kernel_size, stride, padding, dilation,
        height_out, width_out
    );
    return out;
}
'''

pointwise_kernel_source = r'''
__global__ void pointwise_kernel(const float* input, const float* weight, float* output,
                                  int N, int in_ch, int out_ch, int k, int s, int p, int d,
                                  int H_out, int W_out) {
    int idx_h = blockIdx.y * blockDim.y + threadIdx.y;
    int idx_w = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx_h >= H_out || idx_w >= W_out) return;

    for (int oc = 0; oc < out_ch; ++oc) {
        float sum = 0.0f;
        for (int ic = 0; ic < in_ch; ++ic) {
            int ih = idx_h * s + ic * d - p;
            int iw = idx_w * s + ic * d - p;
            if (ih >= 0 && ih < input.shape[2]) &&
               (iw >= 0 && iw < input.shape[3]) {
                // weight[oc*in_ch + ic] scalar for 1x1
                sum += input[(blockIdx.z * N * input.shape[2] * input.shape[3] +
                            (blockIdx.z * N + oc) * input.shape[2] * input.shape[3] +
                            ih * input.shape[3] + iw * input.shape[3])] *
                         weight[oc * in_ch + ic];
            }
        }
        output[(idx_h * W_out + idx_w)] = sum;
    }
}
'''

# ---------- Compile custom CUDA kernels ----------
depthwise_cuda = load_inline(
    name="depthwise_cuda",
    cpp_sources=depthwise_cpp_source,
    cuda_sources=depthwise_kernel_source,
    functions=["depthwise_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

pointwise_cuda = load_inline(
    name="pointwise_cuda",
    cpp_sources=pointwise_cpp_source,
    cuda_sources=pointwise_kernel_source,
    functions=["pointwise_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ----------------------------------------------------------------------
# Optimized model (ModelNew)
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.bias = bias

        # Attach compiled custom functions
        self.depthwise = depthwise_cuda
        self.pointwise = pointwise_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = self.depthwise(x)
        x = self.pointwise(x)
        return x
